from orgops.logging.context import get_request_id

def build_payload(event, level, **fields):
    payload = {"event": event, "level": level}
    payload.update(fields)
    rid = get_request_id()
    if rid is not None:
        payload["request_id"] = rid
    return payload

def to_dict(self):
    # Canonical contract keys only
    return {
        "code": self.code,
        "message": self.message,
        "details": self.details,
        "trace_id": self.trace_id,
    }

